{
  "name": "abpilot",
  "version": "2.0.5",
  "description": "ABPilot CLI: a local UI for the gateway, OpenCode AI chat, and skill apps",
  "type": "module",
  "bin": {
    "abpilot": "bin/abpilot.js"
  },
  "files": [
    "bin",
    "lib",
    "ui/dist",
    "README.md"
  ],
  "scripts": {
    "ui": "node bin/abpilot.js ui",
    "gateway:status": "node bin/abpilot.js gateway status",
    "build:ui": "npm --prefix ui install && npm --prefix ui run build",
    "prepack": "npm run build:ui",
    "test": "node --test test/*.test.mjs"
  },
  "engines": {
    "node": ">=20"
  },
  "keywords": [
    "abpilot",
    "iroh",
    "gateway",
    "opencode",
    "skills"
  ],
  "license": "UNLICENSED",
  "dependencies": {
    "@opencode/cli": "2.3.2",
    "@opencode/client": "2.3.2",
    "express": "^5.2.1",
    "ws": "^8.21.3"
  },
  "allowScripts": {
    "@opencode/cli": true
  }
}

#!/usr/bin/env node

import { main } from "../lib/cli.js";

process.title = "abpilot";

main(process.argv.slice(2)).catch((err) => {
  console.error(`abpilot: ${err?.message ?? err}`);
  process.exitCode = 1;
});

import { readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));

class UsageError extends Error {}

function packageVersion() {
  try {
    return JSON.parse(readFileSync(join(HERE, "..", "package.json"), "utf8")).version ?? "0.0.0";
  } catch {
    return "0.0.0";
  }
}

function needValue(args, index, option) {
  const value = args[index + 1];
  if (value === undefined || value.startsWith("-")) {
    throw new UsageError(`${option} requires a value`);
  }
  return value;
}

function parseOptions(args) {
  const options = { skillsDir: [] };
  const positionals = [];
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === "--") {
      positionals.push(...args.slice(i + 1));
      break;
    }
    if (arg === "-h" || arg === "--help") {
      options.help = true;
    } else if (arg === "-v" || arg === "--version") {
      options.version = true;
    } else if (arg === "--json") {
      options.json = true;
    } else if (arg === "--no-open") {
      options.open = false;
    } else if (arg === "--no-opencode") {
      options.opencode = false;
    } else if (arg === "-p" || arg === "--port") {
      options.port = needValue(args, i, arg);
      i += 1;
    } else if (arg.startsWith("--port=")) {
      options.port = arg.slice("--port=".length);
    } else if (arg === "-H" || arg === "--host") {
      options.host = needValue(args, i, arg);
      i += 1;
    } else if (arg.startsWith("--host=")) {
      options.host = arg.slice("--host=".length);
    } else if (arg === "-g" || arg === "--gateway") {
      options.gateway = needValue(args, i, arg);
      i += 1;
    } else if (arg.startsWith("--gateway=")) {
      options.gateway = arg.slice("--gateway=".length);
    } else if (arg === "--runtime") {
      options.runtime = needValue(args, i, arg);
      i += 1;
    } else if (arg.startsWith("--runtime=")) {
      options.runtime = arg.slice("--runtime=".length);
    } else if (arg === "--cwd") {
      options.cwd = needValue(args, i, arg);
      i += 1;
    } else if (arg.startsWith("--cwd=")) {
      options.cwd = arg.slice("--cwd=".length);
    } else if (arg === "--skills-dir") {
      options.skillsDir.push(needValue(args, i, arg));
      i += 1;
    } else if (arg.startsWith("--skills-dir=")) {
      options.skillsDir.push(arg.slice("--skills-dir=".length));
    } else if (arg === "--state-file") {
      options.stateFile = needValue(args, i, arg);
      i += 1;
    } else if (arg.startsWith("--state-file=")) {
      options.stateFile = arg.slice("--state-file=".length);
    } else if (arg === "--opencode-bin") {
      options.opencodeBin = needValue(args, i, arg);
      i += 1;
    } else if (arg.startsWith("--opencode-bin=")) {
      options.opencodeBin = arg.slice("--opencode-bin=".length);
    } else if (arg === "--opencode-standalone") {
      options.opencodeStandalone = true;
    } else if (arg.startsWith("-")) {
      throw new UsageError(`Unknown option: ${arg}`);
    } else {
      positionals.push(arg);
    }
  }
  return { options, positionals };
}

function helpText() {
  return `ABPilot CLI ${packageVersion()}

Usage:
  abpilot ui [options]              Start the local UI (gateway + AI chat + skill apps)
                                    External access is off by default; enable it
                                    from the ABPilot desktop host
  abpilot gateway [status|routes|services|url] [options]
  abpilot --version
  abpilot --help

UI options:
  -p, --port <port>                 Listen port (default 17622; 0 picks a free port)
  -H, --host <host>                 Listen address (default 127.0.0.1)
  -g, --gateway <url>               Gateway URL (default: read from runtime.json)
      --runtime <file>              Desktop runtime.json (default ~/.abpilot/desktop/runtime.json)
      --cwd <dir>                   Workspace for OpenCode and skill discovery (default: cwd)
      --skills-dir <dir>            Extra skill root; may be repeated
      --state-file <file>           UI state file (default ~/.abpilot/cli/state.json)
      --opencode-bin <path>         Explicit opencode executable
      --opencode-standalone         Run a private opencode server instead of
                                    reusing the shared background service
      --no-opencode                 Do not start AI chat
      --no-open                     Do not open the browser

Gateway options:
  -g, --gateway <url>               Gateway URL
      --runtime <file>              runtime.json path
      --json                        Print JSON

Examples:
  abpilot ui
  abpilot ui --port 17630 --no-open
  abpilot ui --gateway http://127.0.0.1:54067
  abpilot gateway status
  abpilot gateway routes --json

Environment:
  ABPILOT_UI_PORT, ABPILOT_UI_HOST, ABPILOT_GATEWAY_URL,
  ABPILOT_RUNTIME_FILE, ABPILOT_DESKTOP_DIR, ABPILOT_CLI_STATE,
  ABPILOT_OPENCODE_BIN
  ABPILOT_DESKTOP=1 with PORT  Desktop-managed service port; no browser opens
`;
}

function gatewayHelpText() {
  return `Usage:
  abpilot gateway [status|routes|services|url] [--json] [-g URL] [--runtime file]

  status     Gateway reachability, daemon status, route/service counts (default)
  routes     Workdir routes exposed by the gateway
  services   Services registered by the desktop host
  url        Print the gateway base URL (optionally with a path suffix)
`;
}

function formatRuntime(runtime) {
  if (!runtime?.exists) return `not found (${runtime?.path ?? "runtime.json"})`;
  const pid = runtime.pid ? `pid ${runtime.pid}${runtime.alive ? "" : " (not running)"}` : "pid unknown";
  return `${runtime.path} · ${pid}`;
}

function printStatus(status) {
  const reach = status.reachable ? "reachable" : "unreachable";
  console.log(`Gateway:   ${status.gatewayUrl ?? "not configured"} (${reach})`);
  if (status.endpointId) {
    console.log(`Endpoint:  ${status.endpointShort ?? status.endpointId}${status.endpointId.length > 12 ? "..." : ""}`);
    console.log(`           ${status.endpointId}`);
  }
  if (status.apiUrl) console.log(`Daemon:    ${status.apiUrl}`);
  if (status.builtinUrl) console.log(`Desktop:   ${status.builtinUrl}`);
  console.log(`Routes:    ${status.routes?.length ?? 0}`);
  console.log(`Services:  ${status.services?.length ?? 0}`);
  console.log(`Runtime:   ${formatRuntime(status.runtime)}`);
  if (status.daemon?.service !== undefined) {
    console.log(`Service:   ${status.daemon.service ? "running" : "stopped"}`);
  }
  if (status.error) console.log(`Error:     ${status.error}`);
}

function printRoutes(routes) {
  if (!routes.length) {
    console.log("No gateway routes.");
    return;
  }
  for (const route of routes) {
    const id = route.service_id ?? route.serviceId ?? "";
    const worktree = route.worktree ?? "";
    console.log(`${route.workdir ?? route.workdirHash ?? "?"}  ${id}${worktree ? `  ${worktree}` : ""}`);
    console.log(`  -> ${route.base ?? ""}`);
  }
}

function printServices(services) {
  if (!services.length) {
    console.log("No registered services.");
    return;
  }
  for (const service of services) {
    if (typeof service === "string") {
      console.log(service);
      continue;
    }
    const title = service.title ?? service.name ?? service.id ?? "service";
    const status = service.status ?? service.state ?? (service.running === true ? "running" : "");
    const url = service.url ?? service.base ?? service.origin ?? "";
    console.log(`${title}${status ? `  [${status}]` : ""}${url ? `  ${url}` : ""}`);
    console.log(`  ${JSON.stringify(service)}`);
  }
}

async function runGateway(action, options, positionals) {
  const { createGateway } = await import("./gateway.js");
  const gateway = createGateway({
    gatewayUrl: options.gateway,
    runtimePath: options.runtime,
    log: () => {},
  });
  const cmd = action ?? "status";

  if (cmd === "status") {
    const status = await gateway.status({ force: true });
    if (options.json) {
      console.log(JSON.stringify(status, null, 2));
    } else {
      printStatus(status);
    }
    return;
  }

  if (cmd === "routes") {
    if (!gateway.url()) {
      const message = `No gateway found. runtime: ${gateway.info().runtime.path}`;
      if (options.json) console.log(JSON.stringify({ error: message, routes: [] }, null, 2));
      else console.error(message);
      process.exitCode = 1;
      return;
    }
    let routes;
    try {
      routes = await gateway.routes();
    } catch (err) {
      if (options.json) console.log(JSON.stringify({ error: err.message, routes: [] }, null, 2));
      else console.error(`Failed to read routes: ${err.message}`);
      process.exitCode = 1;
      return;
    }
    if (options.json) console.log(JSON.stringify({ routes }, null, 2));
    else printRoutes(routes);
    return;
  }

  if (cmd === "services") {
    if (!gateway.url()) {
      const message = `No gateway found. runtime: ${gateway.info().runtime.path}`;
      if (options.json) console.log(JSON.stringify({ error: message, services: [] }, null, 2));
      else console.error(message);
      process.exitCode = 1;
      return;
    }
    let services;
    try {
      services = await gateway.services();
    } catch (err) {
      if (options.json) console.log(JSON.stringify({ error: err.message, services: [] }, null, 2));
      else console.error(`Failed to read services: ${err.message}`);
      process.exitCode = 1;
      return;
    }
    if (options.json) console.log(JSON.stringify({ services }, null, 2));
    else printServices(services);
    return;
  }

  if (cmd === "url") {
    const base = gateway.url();
    if (!base) {
      const info = gateway.info();
      const message = `No gateway found. runtime: ${info.runtime.path}`;
      if (options.json) console.log(JSON.stringify({ error: message, ...info }, null, 2));
      else console.error(message);
      process.exitCode = 1;
      return;
    }
    const suffix = positionals[0] ?? "";
    const url = suffix ? `${base.replace(/\/+$/, "")}/${suffix.replace(/^\/+/, "")}` : base;
    if (options.json) console.log(JSON.stringify({ url }, null, 2));
    else console.log(url);
    return;
  }

  throw new UsageError(`Unknown gateway subcommand: ${cmd}`);
}

async function runUi(options) {
  const { startUi } = await import("./ui.js");
  const instance = await startUi({
    cwd: options.cwd ? resolve(options.cwd) : process.cwd(),
    port: options.port,
    host: options.host,
    gatewayUrl: options.gateway,
    runtimePath: options.runtime,
    skillsDir: options.skillsDir,
    stateFile: options.stateFile ? resolve(options.stateFile) : undefined,
    opencodeBin: options.opencodeBin,
    opencode: options.opencode !== false,
    opencodeStandalone: options.opencodeStandalone === true,
    open: options.open !== false && process.env.ABPILOT_DESKTOP !== "1",
    log: (msg) => console.log(msg),
    errorLog: (msg) => console.error(msg),
  });

  let closing = false;
  const shutdown = async (signal) => {
    if (closing) return;
    closing = true;
    console.log(`\nReceived ${signal}, shutting down...`);
    try {
      await instance.close();
    } catch (err) {
      console.error(`Shutdown failed: ${err.message}`);
    }
    process.exit(0);
  };
  process.once("SIGINT", () => void shutdown("SIGINT"));
  process.once("SIGTERM", () => void shutdown("SIGTERM"));
  process.once("SIGHUP", () => void shutdown("SIGHUP"));
  return instance;
}

export async function main(argv = process.argv.slice(2)) {
  try {
    const args = [...argv];
    const command = args.length > 0 && !args[0].startsWith("-") ? args.shift() : "help";
    const { options, positionals } = parseOptions(args);

    if (options.version) {
      console.log(packageVersion());
      return;
    }
    if (options.help) {
      if (command === "gateway") console.log(gatewayHelpText());
      else console.log(helpText());
      return;
    }

    if (command === "ui") {
      if (positionals.length > 0) throw new UsageError(`ui does not accept positional arguments: ${positionals.join(" ")}`);
      await runUi(options);
      return;
    }

    if (command === "gateway") {
      const action = positionals.shift();
      await runGateway(action, options, positionals);
      return;
    }

    if (command === "help") {
      console.log(helpText());
      return;
    }

    throw new UsageError(`Unknown command: ${command}`);
  } catch (err) {
    if (err instanceof UsageError) {
      console.error(err.message);
      console.error("");
      console.error(helpText());
      process.exitCode = 2;
      return;
    }
    throw err;
  }
}

export { helpText, gatewayHelpText };
